import re

def count_word_frequencies(text):
    if not text:
        return {}

    # Find all sequences of letters or digits
    words = re.findall(r'[a-zA-Z0-9]+', text)

    # Convert to lowercase and count frequencies
    word_counts = {}
    for word in words:
        lower_word = word.lower()
        word_counts[lower_word] = word_counts.get(lower_word, 0) + 1

    return word_counts

