import urllib.parse

def parse_query_string(query):
    if query.startswith('?'):
        query = query[1:]

    if not query:
        return {}

    # Split the query string into key=value pairs
    pairs = query.split('&')
    result = {}

    for pair in pairs:
        if '=' in pair:
            key, value = pair.split('=', 1)
            # Decode key and value using urllib.parse.unquote
            # unquote handles percent decoding and blank values correctly
            decoded_key = urllib.parse.unquote(key)
            decoded_value = urllib.parse.unquote(value)

            if decoded_key:
                if key not in result:
                    result[key] = []
                result[key].append(decoded_value)
        else:
            # Handle cases where there is no '=' (e.g., just a key)
            # Treat it as a key with an empty string value
            decoded_key = urllib.parse.unquote(pair)
            if decoded_key:
                if decoded_key not in result:
                    result[decoded_key] = []
                result[decoded_key].append('')

    return result

def parse_bool(value):
    """
    Parses common boolean strings.

    Returns True for true, yes, y, 1, on.
    Returns False for false, no, n, 0, off.
    Matching is case-insensitive after stripping.
    Raises ValueError otherwise.
    """
    if not isinstance(value, str):
        raise ValueError("Input must be a string")

    stripped_value = value.strip().lower()

    true_values = {"true", "yes", "y", "1", "on"}
    false_values = {"false", "no", "n", "0", "off"}

    if stripped_value in true_values:
        return True
    elif stripped_value in false_values:
        return False
    else:
        raise ValueError(f"Invalid boolean value: {value}")

