def percent_change(old, new):
    if old == 0:
        raise ValueError("Cannot calculate percent change when the old value is zero.")
    return ((new - old) / old) * 100

def clamp_numbers(values, low, high):
    if low > high:
        raise ValueError("low cannot be greater than high")

    result = []
    for x in values:
        if x < low:
            result.append(low)
        elif x > high:
            result.append(high)
        else:
            result.append(x)
    return result

