def validate_relative_path(path):
        # ... (long if condition)
        if not path or path.startswith('/') or path.startswith('\\') or (len(path) > 1 and path[1] == ':' and path[0].isalpha()):
            # ...
            p = Path(path)
            if p.is_absolute():
                return False

        # Check for '..' segments
        if '..' in path:
            return False

        # Re-check absolute path using Path object for robustness
        p = Path(path)
        if p.is_absolute():
            return False

        return True

