def json_get_path(data, path, default=None):
    """
    Return a nested value from dict/list data using a dot-separated path.
    Numeric path parts index lists. Return default if any part is missing or invalid.
    """
    if not path:
        return data

    keys = [key.strip() for key in path.split('.')]
    current = data

    for key in keys:
        if isinstance(current, dict):
            if key in current:
                current = current[key]
            else:
                return default
        elif isinstance(current, list):
            try:
                index = int(key)
                if 0 <= index < len(current):
                    current = current[index]
                else:
                    return default
            except ValueError:
                # If it's not a valid integer index for a list, treat it as missing
                return default
        else:
            # If we expect a dict/list but found something else (like a string or int)
            # and we still have path parts, the path is invalid.
            return default

    return current

