import collections

def validate_parentheses(text):
    """
    Validates if the parentheses (), [], and {} brackets are balanced and 
    correctly nested in the given text. Ignores non-bracket characters.
    """
    stack = []
    mapping = {
        ')': '(',
        ']': '[',
        '}': '{'
    }
    open_brackets = set(['(', '[', '{'])

    for char in text:
        if char in open_brackets:
            stack.append(char)
        elif char in mapping:
            if not stack or stack.pop() != mapping[char]:
                return False

    return not stack

def expand_ranges(ranges):
    """
    Expand inclusive (start, end) ranges into a flat list.
    Raises ValueError if any start is greater than end.
    """
    expanded_list = []
    for start, end in ranges:
        if start > end:
            raise ValueError(f"Invalid range: start ({start}) cannot be greater than end ({end})")

        # Generate the sequence from start to end (inclusive)
        for i in range(start, end + 1):
            expanded_list.append(i)

    return expanded_list

